select * from pizza_types;
select * from orders;
select * from pizza_types;
select * from order_details;
select * from pizzas;


-- Q1 -> Retrive the Totall no of Order Placed

select count(order_id) as total_order from orders;

-- Q2 ->Calculate The totall revenew generated by the pizza sales
select 
ROUND(sum(order_details.quantity*pizzas.price),1) as revenew
from order_details join pizzas
on pizzas.pizza_type_id = order_details.pizza_id;

-- Q3 -> Identify the highest-priced pizza.

select pizza_types.name,pizzas.price
from pizza_types join pizzas
on pizza_types.pizza_type_id = pizzas.pizza_name
order by pizzas.price desc
limit 1;

-- Q4 Identifay the no of times the same quantity of pizza ordered

select quantity , count(order_details_id)
from order_details group by quantity;

-- Q5 Identify the most common pizza size ordered

select pizzas.size,count(order_details.order_details_id) as ord_count
from pizzas join order_details
on pizzas.pizza_type_id = order_details.pizza_id
GROUP BY pizzas.size 
order by ord_count DESC;

-- Q6 List the top 5 most ordered pizza types along with their quantities
select pizza_types.name,
sum(order_details.quantity) as old1
from pizza_types join pizzas
on pizza_types.pizza_type_id = pizzas.pizza_name
JOIN order_details
on order_details.pizza_id = pizzas.pizza_type_id
GROUP BY pizza_types.name
ORDER BY old1 DESC
limit 5;








































